#!/usr/bin/env python3
"""PSS Single-File Edition (v1.0.0-rc1) — self-extracting.

Core source is gzip+base64 embedded so the full module stays one file
while remaining small enough for transport. Behavior is identical to the
plain pss_single.py (Mission / Gate / PredictionPolicy / compile balanced|strict).
"""
from __future__ import annotations
import base64
import gzip

_SRC_B64 = """
"""

exec(
    compile(
        gzip.decompress(base64.b64decode(_SRC_B64)),
        "pss_single.py",
        "exec",
    ),
    globals(),
)

if __name__ == "__main__":
    main()  # noqa: F821 — defined by exec'd source
